package com.tracking_service.Config;
import java.util.Base64; import javax.crypto.SecretKey; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.oauth2.jwt.JwtDecoder; import org.springframework.security.oauth2.jwt.NimbusJwtDecoder; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter())));return h.build();} @Bean JwtDecoder jwtDecoder(@Value("${jwt.secret}")String s){SecretKey k=new SecretKeySpec(Base64.getDecoder().decode(s),"HmacSHA256");return NimbusJwtDecoder.withSecretKey(k).build();} @Bean JwtAuthenticationConverter converter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(j->java.util.List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+j.getClaimAsString("role"))));return c;} }
